"use client";

import { useEffect, useState } from "react";

const API_BASE =
  process.env.NEXT_PUBLIC_API_BASE_URL ?? "https://laravel.test:4430";

type KPI = {
  total: number;
  needs_review: number;
  auto_accept: number;
  rejected: number;
  approval_rate: number;
};

function KpiRow({
  label,
  value,
  total,
}: {
  label: string;
  value: number;
  total: number;
}) {
  const rate = total ? (value / total) * 100 : 0;

  return (
    <div style={{ marginBottom: 16 }}>
      <div>
        {label}: {value}
      </div>
      <div style={{ height: 6, background: "#eee" }}>
        <div
          style={{
            width: `${rate}%`,
            height: "100%",
            background: "#2563eb",
          }}
        />
      </div>
    </div>
  );
}

export default function DashboardPage() {
  const [kpi, setKpi] = useState<KPI | null>(null);

  useEffect(() => {
    fetch(`${API_BASE}/api/entity-kpis`, {
      credentials: "include",
    })
      .then((r) => r.json())
      .then(setKpi);
  }, []);

  if (!kpi) return <p>Loading...</p>;

  return (
    <div style={{ padding: 24 }}>
      <h1>AI Operation Dashboard</h1>

      <KpiRow label="Total" value={kpi.total} total={kpi.total} />
      <KpiRow label="Needs Review" value={kpi.needs_review} total={kpi.total} />
      <KpiRow label="Auto Accept" value={kpi.auto_accept} total={kpi.total} />
      <KpiRow label="Rejected" value={kpi.rejected} total={kpi.total} />

      <div style={{ marginTop: 12 }}>Approval Rate: {kpi.approval_rate}%</div>
    </div>
  );
}
